extern crate rei_microphysics;pub use rei_microphysics::*;
#[path="/home/cosmosapjw/Dropbox/bianchi/rei_bianchi/rust/rei_microphysics/src/coupled_primary.rs"] pub mod coupled_primary;use coupled_primary::*;
fn arr(v:&[f64]){print!("[");for(i,x)in v.iter().enumerate(){if i>0{print!(",");}print!("{:.17e}",x);}print!("]");}
fn ib(v:&[Interval]){print!("[");for(i,x)in v.iter().enumerate(){if i>0{print!(",");}arr(&[x.lo,x.hi]);}print!("]");}
fn main(){let m=Ft03Model::controlled().unwrap();let s=m.initial_state();let old=PrimaryState{fractions:s.fractions,w_ev_per_h:s.u_erg_cm3/(m.gas.n_h_cm3*m.gas.ev_erg),escape_ev_per_h:0.,packets:vec![PrimaryPacket{energy_ev:13.7,per_h:0.05},PrimaryPacket{energy_ev:35.,per_h:0.005},PrimaryPacket{energy_ev:70.,per_h:0.001}]};let stage=PrimaryStage{n_h_cm3:1e-4,f_he:0.083,h_mean_per_s:1e-14};let centre=[old.fractions[0],old.fractions[1],old.fractions[2],old.w_ev_per_h];let radii=[1e-7,1e-7,1e-7,1e-5];let gas=std::array::from_fn(|i|{let z=Interval::point(centre[i]).unwrap();let d=Interval::point(radii[i]).unwrap();Interval::new(z.sub(&d).unwrap().lo,z.add(&d).unwrap().hi).unwrap()});let photons=old.packets.iter().map(|p|{let z=Interval::point(p.per_h).unwrap();let d=Interval::point(1e-8).unwrap();Interval::new(z.sub(&d).unwrap().lo,z.add(&d).unwrap().hi).unwrap()}).collect();let parent=PrimaryBox{gas,photons};let q=primary_stage_root(&stage,&old,&parent,1e9,StepControl{max_iterations:200,residual_tolerance:1e-14}).unwrap();print!("{{\"centre\":");arr(&q.centre);print!(",\"gas\":");ib(&q.gas);print!(",\"photons\":");ib(&q.photons);print!(",\"parent_gas\":");ib(&parent.gas);print!(",\"parent_photons\":");ib(&parent.photons);print!(",\"C\":[");for(i,row)in q.preconditioner.iter().enumerate(){if i>0{print!(",");}arr(row);}println!("]}}");}
